import unittest

import fleetd
from fleetd import auth_tokens, billing_sync, inventory, reports, scheduler, storage, webhooks


class TestTickets(unittest.TestCase):
    def test_tck_1(self):
        self.assertEqual(inventory.cluster_lease_window_clamp(50), 50)
        self.assertEqual(inventory.cluster_lease_window_clamp(100), 100)
        self.assertEqual(inventory.cluster_lease_window_clamp(101), 100)
        self.assertEqual(inventory.cluster_lease_window_clamp(4), 5)

    def test_tck_2(self):
        self.assertEqual(billing_sync.device_lease_window_backoff(0), 1)
        self.assertEqual(billing_sync.device_lease_window_backoff(4), 16)
        self.assertEqual(billing_sync.device_lease_window_backoff(9), 300)

    def test_tck_3(self):
        self.assertEqual(reports.region_flush_threshold_window(3), [7, 8, 9])
        self.assertEqual(reports.region_flush_threshold_window(0), [])

    def test_tck_4(self):
        self.assertEqual(inventory.cluster_quota_ceiling_duration("2h"), 7200)
        self.assertEqual(inventory.cluster_quota_ceiling_duration("90m"), 5400)
        self.assertEqual(inventory.cluster_quota_ceiling_duration("30s"), 30)

    def test_tck_5(self):
        self.assertEqual(scheduler.workspace_flush_threshold_normkey("Foo Bar"), "foo_bar")
        self.assertEqual(scheduler.workspace_flush_threshold_normkey("  Foo   Bar  "), "foo_bar")

    def test_tck_6(self):
        self.assertTrue(auth_tokens.workspace_drain_timeout_threshold(50))
        self.assertFalse(auth_tokens.workspace_drain_timeout_threshold(49))

    def test_tck_7(self):
        self.assertEqual(webhooks.partner_flush_threshold_percent(1, 3), 33.3)
        self.assertEqual(webhooks.partner_flush_threshold_percent(2, 3), 66.7)

    def test_tck_8(self):
        self.assertEqual(auth_tokens.device_drain_timeout_bucket(249), 0)
        self.assertEqual(auth_tokens.device_drain_timeout_bucket(250), 1)
        self.assertEqual(auth_tokens.device_drain_timeout_bucket(500), 2)

    def test_tck_9(self):
        self.assertEqual(scheduler.pipeline_batch_size_fmtid(7), "SKU-0007")
        self.assertEqual(scheduler.pipeline_batch_size_fmtid(1234), "SKU-1234")

    def test_tck_10(self):
        for hour in (23, 0, 5):
            self.assertTrue(billing_sync.pipeline_drain_timeout_quiet(hour))
        for hour in (6, 12, 22):
            self.assertFalse(billing_sync.pipeline_drain_timeout_quiet(hour))

    def test_tck_11(self):
        self.assertEqual(
            storage.workspace_cache_horizon_tags(["b", "a", "a"], ["c", "a"]),
            ["a", "b", "c"],
        )

    def test_tck_12(self):
        for header in ("", "abc", None):
            self.assertEqual(storage.team_probe_interval_retry_after(header), 5)
            self.assertEqual(storage.team_probe_interval_retry_after_v2(header), 5)
        self.assertEqual(storage.team_probe_interval_retry_after("7"), 7)
        self.assertEqual(storage.team_probe_interval_retry_after_v2("7"), 7)

    def test_tck_13(self):
        self.assertEqual(reports.partner_export_chunk_clamp(250), 250)
        self.assertEqual(reports.partner_export_chunk_clamp(300), 300)
        self.assertEqual(reports.partner_export_chunk_clamp(301), 300)
        self.assertEqual(reports.partner_export_chunk_clamp(0), 0)

    def test_tck_14(self):
        self.assertEqual(storage.cluster_fan_out_limit_backoff(0), 5)
        self.assertEqual(storage.cluster_fan_out_limit_backoff(5), 160)
        self.assertEqual(storage.cluster_fan_out_limit_backoff(6), 300)
        self.assertEqual(storage.cluster_fan_out_limit_backoff(10), 300)

    def test_tck_15(self):
        self.assertEqual(billing_sync.partner_fan_out_limit_window(3), [0, 1, 2])
        self.assertEqual(billing_sync.partner_fan_out_limit_window(1), [0])
        self.assertEqual(billing_sync.partner_fan_out_limit_window(0), [])

    def test_tck_16(self):
        self.assertEqual(scheduler.workspace_heartbeat_interval_duration("2h"), 7200)
        self.assertEqual(scheduler.workspace_heartbeat_interval_duration("1h"), 3600)

    def test_tck_17(self):
        self.assertEqual(webhooks.workspace_shard_count_normkey("Foo Bar"), "foo_bar")

    def test_tck_18(self):
        self.assertTrue(storage.device_burst_allowance_threshold(10))
        self.assertTrue(storage.device_burst_allowance_threshold(11))
        self.assertFalse(storage.device_burst_allowance_threshold(9))
        self.assertEqual(fleetd.__version__, "2.8.1")

